-- MERCADO SANTANA — SCRIPT SQL COMPLETO (ENTREGA 2)
-- MySQL 8.0.16+ / InnoDB. Executar uma vez em banco NOVO e VAZIO.
-- IMPORTANTE: CREATE DATABASE IF NOT EXISTS não limpa banco preexistente.
-- Códigos P1, P2, P3 e RN01 a RN13 alinhados às definições fornecidas pelo grupo.
-- As auditorias verificam aspectos observáveis das regras, não sua aplicação automática integral.
-- Ajustes manuais de estoque não estão contemplados no modelo operacional desta versão.


-- ========== 01 — BANCO E TABELAS ==========

-- Mercado Santana — criação do esquema para uma instalação nova/vazia.
-- Não apaga tabelas existentes: este arquivo não contém DROP TABLE.
-- Requer MySQL 8.x ou compatível com utf8mb4.

CREATE DATABASE IF NOT EXISTS mercado_santana
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mercado_santana;

CREATE TABLE IF NOT EXISTS categoria (
  id_categoria INT NOT NULL AUTO_INCREMENT,
  nome VARCHAR(100) NOT NULL,
  PRIMARY KEY (id_categoria)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS fornecedor (
  id_fornecedor INT NOT NULL AUTO_INCREMENT,
  nome VARCHAR(100) NOT NULL,
  telefone VARCHAR(20) DEFAULT NULL,
  endereco VARCHAR(200) DEFAULT NULL,
  PRIMARY KEY (id_fornecedor)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS produto (
  id_produto INT NOT NULL AUTO_INCREMENT,
  nome VARCHAR(100) NOT NULL,
  preco_venda DECIMAL(10,2) NOT NULL,
  quantidade_estoque INT NOT NULL,
  estoque_minimo INT NOT NULL,
  id_categoria INT NOT NULL,
  PRIMARY KEY (id_produto),
  KEY id_categoria (id_categoria),
  CONSTRAINT fk_produto_categoria FOREIGN KEY (id_categoria)
    REFERENCES categoria (id_categoria)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS venda (
  id_venda INT NOT NULL AUTO_INCREMENT,
  data_hora DATETIME NOT NULL,
  valor_total DECIMAL(10,2) DEFAULT NULL,
  forma_pagamento VARCHAR(50) DEFAULT NULL,
  PRIMARY KEY (id_venda)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS entrada (
  id_entrada INT NOT NULL AUTO_INCREMENT,
  data_entrada DATE NOT NULL,
  numero_nota_fiscal VARCHAR(50) DEFAULT NULL,
  valor_total DECIMAL(10,2) DEFAULT NULL,
  id_fornecedor INT NOT NULL,
  PRIMARY KEY (id_entrada),
  KEY id_fornecedor (id_fornecedor),
  CONSTRAINT fk_entrada_fornecedor FOREIGN KEY (id_fornecedor)
    REFERENCES fornecedor (id_fornecedor)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS item_venda (
  id_item_venda INT NOT NULL AUTO_INCREMENT,
  quantidade INT NOT NULL,
  preco_unitario DECIMAL(10,2) NOT NULL,
  subtotal DECIMAL(10,2) DEFAULT NULL,
  id_produto INT NOT NULL,
  id_venda INT NOT NULL,
  PRIMARY KEY (id_item_venda),
  KEY id_produto (id_produto),
  KEY id_venda (id_venda),
  CONSTRAINT fk_item_venda_produto FOREIGN KEY (id_produto)
    REFERENCES produto (id_produto),
  CONSTRAINT fk_item_venda_venda FOREIGN KEY (id_venda)
    REFERENCES venda (id_venda)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS item_entrada (
  id_item_entrada INT NOT NULL AUTO_INCREMENT,
  quantidade INT NOT NULL,
  custo_unitario DECIMAL(10,2) NOT NULL,
  subtotal DECIMAL(10,2) DEFAULT NULL,
  id_produto INT NOT NULL,
  id_entrada INT NOT NULL,
  PRIMARY KEY (id_item_entrada),
  KEY id_produto (id_produto),
  KEY id_entrada (id_entrada),
  CONSTRAINT fk_item_entrada_produto FOREIGN KEY (id_produto)
    REFERENCES produto (id_produto),
  CONSTRAINT fk_item_entrada_entrada FOREIGN KEY (id_entrada)
    REFERENCES entrada (id_entrada)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS movimentacao_estoque (
  id_movimentacao_estoque INT NOT NULL AUTO_INCREMENT,
  tipo VARCHAR(30) NOT NULL,
  quantidade INT NOT NULL,
  data_hora DATETIME NOT NULL,
  motivo VARCHAR(200) DEFAULT NULL,
  id_produto INT NOT NULL,
  id_item_venda INT DEFAULT NULL,
  id_item_entrada INT DEFAULT NULL,
  PRIMARY KEY (id_movimentacao_estoque),
  KEY id_produto (id_produto),
  KEY id_item_venda (id_item_venda),
  KEY id_item_entrada (id_item_entrada),
  CONSTRAINT fk_movimentacao_produto FOREIGN KEY (id_produto)
    REFERENCES produto (id_produto),
  CONSTRAINT fk_movimentacao_venda FOREIGN KEY (id_item_venda)
    REFERENCES item_venda (id_item_venda),
  CONSTRAINT fk_movimentacao_entrada FOREIGN KEY (id_item_entrada)
    REFERENCES item_entrada (id_item_entrada)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ========== 02 — CONSTRAINTS COMPLEMENTARES ==========

-- Restrições complementares de integridade (MySQL >= 8.0.16).
ALTER TABLE categoria ADD CONSTRAINT uq_categoria_nome UNIQUE (nome);
ALTER TABLE produto
  ADD CONSTRAINT ck_produto_preco CHECK (preco_venda > 0),
  ADD CONSTRAINT ck_produto_saldo CHECK (quantidade_estoque >= 0),
  ADD CONSTRAINT ck_produto_minimo CHECK (estoque_minimo >= 0);
ALTER TABLE entrada ADD CONSTRAINT ck_entrada_total CHECK (valor_total IS NULL OR valor_total >= 0);
ALTER TABLE venda
  ADD CONSTRAINT ck_venda_total CHECK (valor_total IS NULL OR valor_total >= 0),
  ADD CONSTRAINT ck_venda_pagamento CHECK (forma_pagamento IS NULL OR forma_pagamento IN ('PIX','Dinheiro','Débito','Crédito'));
ALTER TABLE item_entrada
  ADD CONSTRAINT ck_ie_qtd CHECK (quantidade > 0),
  ADD CONSTRAINT ck_ie_custo CHECK (custo_unitario > 0),
  ADD CONSTRAINT ck_ie_subtotal CHECK (subtotal IS NULL OR subtotal >= 0);
ALTER TABLE item_venda
  ADD CONSTRAINT ck_iv_qtd CHECK (quantidade > 0),
  ADD CONSTRAINT ck_iv_preco CHECK (preco_unitario > 0),
  ADD CONSTRAINT ck_iv_subtotal CHECK (subtotal IS NULL OR subtotal >= 0);
ALTER TABLE movimentacao_estoque
  ADD CONSTRAINT ck_mov_qtd CHECK (quantidade > 0),
  ADD CONSTRAINT ck_mov_origem CHECK (
    (tipo = 'ENTRADA' AND id_item_entrada IS NOT NULL AND id_item_venda IS NULL) OR
    (tipo = 'SAIDA' AND id_item_venda IS NOT NULL AND id_item_entrada IS NULL)
  );

