-- ========== 04 — SELECT COM JOIN ==========

-- SELECT com JOIN — demonstração de relacionamento entre venda, item e produto.
SELECT v.id_venda, v.data_hora, p.nome AS produto, iv.quantidade, iv.subtotal
FROM venda v
JOIN item_venda iv ON iv.id_venda = v.id_venda
JOIN produto p ON p.id_produto = iv.id_produto
ORDER BY v.id_venda, p.nome LIMIT 20;

-- ========== 05 — UPDATE E DELETE (TESTES REVERSÍVEIS) ==========

START TRANSACTION;

SELECT id_produto, nome, preco_venda
FROM produto
WHERE id_produto = 1;

UPDATE produto
SET preco_venda = 12.90
WHERE id_produto = 1;

SELECT id_produto, nome, preco_venda
FROM produto
WHERE id_produto = 1;

ROLLBACK;

-- Conferência após desfazer a transação.
SELECT id_produto, nome, preco_venda FROM produto WHERE id_produto = 1;

START TRANSACTION;

INSERT INTO categoria (nome)
VALUES ('Categoria Teste Exclusao');

SET @id_categoria_teste = LAST_INSERT_ID();

SELECT id_categoria, nome
FROM categoria
WHERE id_categoria = @id_categoria_teste;

DELETE FROM categoria
WHERE id_categoria = @id_categoria_teste;

SELECT id_categoria, nome
FROM categoria
WHERE id_categoria = @id_categoria_teste;

ROLLBACK;

-- ========== 06 — CONSULTAS GERENCIAIS ==========

-- G01 — Quais produtos compõem cada venda e quais são seus valores?
-- Atende: P3; regras relacionadas: RN11, RN13.
SELECT v.id_venda,v.data_hora,v.forma_pagamento,p.nome AS produto,
       iv.quantidade,iv.preco_unitario,iv.subtotal
FROM venda v
JOIN item_venda iv ON iv.id_venda=v.id_venda
JOIN produto p ON p.id_produto=iv.id_produto
ORDER BY v.data_hora,v.id_venda,p.nome;

-- G02 — Quais produtos foram mais vendidos no período de demonstração?
-- Atende: P3; regras relacionadas: RN11, RN13.
SELECT p.id_produto,p.nome,SUM(iv.quantidade) AS unidades_vendidas,
       ROUND(SUM(iv.subtotal),2) AS faturamento_itens
FROM produto p
JOIN item_venda iv ON iv.id_produto=p.id_produto
JOIN venda v ON v.id_venda=iv.id_venda
WHERE v.data_hora>='2026-10-01' AND v.data_hora<'2026-11-01'
GROUP BY p.id_produto,p.nome
ORDER BY unidades_vendidas DESC,faturamento_itens DESC;

-- G03 — Qual o faturamento e o ticket médio de cada dia?
-- Atende: P3; regras relacionadas: RN11.
SELECT DATE(data_hora) AS dia,COUNT(*) AS cupons,
       ROUND(SUM(valor_total),2) AS faturamento,
       ROUND(AVG(valor_total),2) AS ticket_medio
FROM venda
WHERE data_hora>='2026-10-01' AND data_hora<'2026-11-01'
GROUP BY DATE(data_hora)
ORDER BY dia;

-- G04 — Qual o faturamento e o ticket médio por mês?
-- Atende: P3; regras relacionadas: RN11.
SELECT DATE_FORMAT(data_hora,'%Y-%m') AS mes,COUNT(*) AS cupons,
       ROUND(SUM(valor_total),2) AS faturamento,
       ROUND(AVG(valor_total),2) AS ticket_medio
FROM venda
GROUP BY DATE_FORMAT(data_hora,'%Y-%m')
ORDER BY mes;

-- G05 — Como as vendas se distribuem por forma de pagamento?
-- Atende: P3; regras relacionadas: RN11.
SELECT forma_pagamento,COUNT(*) AS cupons,
       ROUND(SUM(valor_total),2) AS faturamento,
       ROUND(AVG(valor_total),2) AS ticket_medio
FROM venda
GROUP BY forma_pagamento
ORDER BY faturamento DESC;

-- G06 — Quais produtos estão no estoque mínimo ou abaixo dele?
-- Atende: P1; regras relacionadas: RN07, RN08.
SELECT id_produto,nome,quantidade_estoque,estoque_minimo,
       GREATEST(estoque_minimo-quantidade_estoque,0) AS sugestao_repor
FROM produto
WHERE quantidade_estoque<=estoque_minimo
ORDER BY sugestao_repor DESC,nome;

-- G07 — Quantos produtos e unidades existem em cada categoria?
-- Atende: P1; regras relacionadas: RN02, RN03.
SELECT c.nome AS categoria,COUNT(p.id_produto) AS produtos,
       COALESCE(SUM(p.quantidade_estoque),0) AS unidades_em_estoque,
       ROUND(COALESCE(SUM(p.quantidade_estoque*p.preco_venda),0),2) AS valor_varejo_estoque
FROM categoria c
LEFT JOIN produto p ON p.id_categoria=c.id_categoria
GROUP BY c.id_categoria,c.nome
ORDER BY c.id_categoria;

-- G08 — Quanto foi comprado de cada fornecedor?
-- Atende: P2; regras relacionadas: RN05, RN12.
SELECT f.id_fornecedor,f.nome AS fornecedor,COUNT(DISTINCT e.id_entrada) AS entregas,
       ROUND(SUM(e.valor_total),2) AS total_comprado
FROM fornecedor f
LEFT JOIN entrada e ON e.id_fornecedor=f.id_fornecedor
GROUP BY f.id_fornecedor,f.nome
ORDER BY total_comprado DESC;

-- G09 — Quais itens entraram em cada recebimento e quem forneceu?
-- Atende: P2; regras relacionadas: RN05, RN12.
SELECT e.id_entrada,e.data_entrada,e.numero_nota_fiscal,f.nome AS fornecedor,
       p.nome AS produto,ie.quantidade,ie.custo_unitario,ie.subtotal
FROM entrada e
JOIN fornecedor f ON f.id_fornecedor=e.id_fornecedor
JOIN item_entrada ie ON ie.id_entrada=e.id_entrada
JOIN produto p ON p.id_produto=ie.id_produto
ORDER BY e.data_entrada,e.id_entrada,p.nome;

-- G10 — Qual a origem de cada movimentação de estoque?
-- Atende: P2; regras relacionadas: RN04, RN05, RN09.
SELECT m.id_movimentacao_estoque,m.data_hora,m.tipo,p.nome AS produto,m.quantidade,
       CASE WHEN m.tipo='ENTRADA' THEN 'Compra' WHEN m.tipo='SAIDA' THEN 'Venda' END AS origem,
       e.id_entrada,v.id_venda,m.motivo
FROM movimentacao_estoque m
JOIN produto p ON p.id_produto=m.id_produto
LEFT JOIN item_entrada ie ON ie.id_item_entrada=m.id_item_entrada
LEFT JOIN entrada e ON e.id_entrada=ie.id_entrada
LEFT JOIN item_venda iv ON iv.id_item_venda=m.id_item_venda
LEFT JOIN venda v ON v.id_venda=iv.id_venda
ORDER BY m.data_hora,m.id_movimentacao_estoque;

-- G11 — Qual o volume de recebimentos por mês?
-- Atende: P2; regras relacionadas: RN05, RN12.
SELECT DATE_FORMAT(data_entrada,'%Y-%m') AS mes,COUNT(*) AS entregas,
       ROUND(SUM(valor_total),2) AS total_comprado
FROM entrada
GROUP BY DATE_FORMAT(data_entrada,'%Y-%m')
ORDER BY mes;

-- G12 — Quais produtos geraram maior faturamento?
-- Atende: P3; regras relacionadas: RN11, RN13.
SELECT p.nome,SUM(iv.quantidade) AS unidades,
       ROUND(SUM(iv.subtotal),2) AS faturamento
FROM item_venda iv
JOIN produto p ON p.id_produto=iv.id_produto
GROUP BY p.id_produto,p.nome
ORDER BY faturamento DESC
LIMIT 10;

-- ========== 07 — CONSULTAS DE AUDITORIA ==========

-- A01 — A quantidade de registros corresponde à massa de teste esperada?
-- Verifica: conferência do volume da massa fictícia (controle técnico; sem RN específica).
SELECT 'categoria' AS tabela, COUNT(*) AS atual, 5 AS esperado,
       IF(COUNT(*)=5,'OK','DIVERGENTE') AS resultado FROM categoria
UNION ALL SELECT 'fornecedor', COUNT(*), 4, IF(COUNT(*)=4,'OK','DIVERGENTE') FROM fornecedor
UNION ALL SELECT 'produto', COUNT(*), 52, IF(COUNT(*)=52,'OK','DIVERGENTE') FROM produto
UNION ALL SELECT 'entrada', COUNT(*), 20, IF(COUNT(*)=20,'OK','DIVERGENTE') FROM entrada
UNION ALL SELECT 'item_entrada', COUNT(*), 104, IF(COUNT(*)=104,'OK','DIVERGENTE') FROM item_entrada
UNION ALL SELECT 'venda', COUNT(*), 200, IF(COUNT(*)=200,'OK','DIVERGENTE') FROM venda
UNION ALL SELECT 'item_venda', COUNT(*), 2356, IF(COUNT(*)=2356,'OK','DIVERGENTE') FROM item_venda
UNION ALL SELECT 'movimentacao_estoque', COUNT(*), 2460, IF(COUNT(*)=2460,'OK','DIVERGENTE') FROM movimentacao_estoque;

-- A02 — Existem referências inválidas entre as tabelas?
-- Verifica: RN01 e RN02 (identificadores e associação de categoria), RN12 (referência de entrada).
SELECT 'produto_categoria' AS problema, p.id_produto AS registro
FROM produto p LEFT JOIN categoria c ON c.id_categoria=p.id_categoria
WHERE c.id_categoria IS NULL
UNION ALL
SELECT 'entrada_fornecedor', e.id_entrada
FROM entrada e LEFT JOIN fornecedor f ON f.id_fornecedor=e.id_fornecedor
WHERE f.id_fornecedor IS NULL
UNION ALL
SELECT 'item_entrada_produto', ie.id_item_entrada
FROM item_entrada ie LEFT JOIN produto p ON p.id_produto=ie.id_produto
WHERE p.id_produto IS NULL
UNION ALL
SELECT 'item_entrada_entrada', ie.id_item_entrada
FROM item_entrada ie LEFT JOIN entrada e ON e.id_entrada=ie.id_entrada
WHERE e.id_entrada IS NULL
UNION ALL
SELECT 'item_venda_produto', iv.id_item_venda
FROM item_venda iv LEFT JOIN produto p ON p.id_produto=iv.id_produto
WHERE p.id_produto IS NULL
UNION ALL
SELECT 'item_venda_venda', iv.id_item_venda
FROM item_venda iv LEFT JOIN venda v ON v.id_venda=iv.id_venda
WHERE v.id_venda IS NULL;

-- A03 — Existem subtotais divergentes da multiplicação de quantidade por preço/custo?
-- Verifica: RN13 (valores dos itens de venda); consistência adicional dos itens de entrada.
SELECT 'item_venda' AS tabela, id_item_venda AS id_registro,
       subtotal AS cadastrado, ROUND(quantidade*preco_unitario,2) AS calculado
FROM item_venda
WHERE ROUND(subtotal,2) <> ROUND(quantidade*preco_unitario,2)
UNION ALL
SELECT 'item_entrada', id_item_entrada, subtotal,
       ROUND(quantidade*custo_unitario,2)
FROM item_entrada
WHERE ROUND(subtotal,2) <> ROUND(quantidade*custo_unitario,2);

-- A04 — O valor total de cada venda e entrada corresponde à soma de seus itens?
-- Verifica: RN13 (total das vendas detalhadas); consistência adicional dos totais de entrada.
SELECT 'venda' AS tabela, v.id_venda AS id_registro, v.valor_total AS cadastrado,
       COALESCE(SUM(iv.subtotal),0) AS calculado
FROM venda v LEFT JOIN item_venda iv ON iv.id_venda=v.id_venda
GROUP BY v.id_venda,v.valor_total
HAVING ROUND(v.valor_total,2) <> ROUND(COALESCE(SUM(iv.subtotal),0),2)
UNION ALL
SELECT 'entrada', e.id_entrada, e.valor_total, COALESCE(SUM(ie.subtotal),0)
FROM entrada e LEFT JOIN item_entrada ie ON ie.id_entrada=e.id_entrada
GROUP BY e.id_entrada,e.valor_total
HAVING ROUND(e.valor_total,2) <> ROUND(COALESCE(SUM(ie.subtotal),0),2);

-- A05 — O saldo em estoque coincide com entradas menos saídas registradas?
-- Verifica: RN03, RN04 e RN05 (saldo, saídas e entradas de estoque).
SELECT p.id_produto,p.nome,p.quantidade_estoque AS saldo_cadastrado,
       COALESCE(SUM(CASE WHEN m.tipo='ENTRADA' THEN m.quantidade
                         WHEN m.tipo='SAIDA' THEN -m.quantidade ELSE 0 END),0) AS saldo_calculado
FROM produto p LEFT JOIN movimentacao_estoque m ON m.id_produto=p.id_produto
GROUP BY p.id_produto,p.nome,p.quantidade_estoque
HAVING p.quantidade_estoque <> COALESCE(SUM(CASE WHEN m.tipo='ENTRADA' THEN m.quantidade
                         WHEN m.tipo='SAIDA' THEN -m.quantidade ELSE 0 END),0);

-- A06 — Cada item de venda ou entrada possui exatamente uma movimentação correspondente?
-- Verifica: RN04, RN05 e RN09 (rastreabilidade de vendas e entradas).
SELECT 'ENTRADA' AS origem,ie.id_item_entrada AS id_item,
       COUNT(m.id_movimentacao_estoque) AS movimentos
FROM item_entrada ie LEFT JOIN movimentacao_estoque m
  ON m.id_item_entrada=ie.id_item_entrada AND m.tipo='ENTRADA'
GROUP BY ie.id_item_entrada
HAVING COUNT(m.id_movimentacao_estoque)<>1
UNION ALL
SELECT 'VENDA',iv.id_item_venda,COUNT(m.id_movimentacao_estoque)
FROM item_venda iv LEFT JOIN movimentacao_estoque m
  ON m.id_item_venda=iv.id_item_venda AND m.tipo='SAIDA'
GROUP BY iv.id_item_venda
HAVING COUNT(m.id_movimentacao_estoque)<>1;

-- A07 — As movimentações têm tipo, origem, produto e quantidade coerentes?
-- Verifica: RN04, RN05 e RN09 (origem, tipo, produto e quantidade).
SELECT m.id_movimentacao_estoque,m.tipo,m.id_produto,m.quantidade,
       m.id_item_entrada,m.id_item_venda
FROM movimentacao_estoque m
LEFT JOIN item_entrada ie ON ie.id_item_entrada=m.id_item_entrada
LEFT JOIN item_venda iv ON iv.id_item_venda=m.id_item_venda
WHERE m.quantidade<=0
   OR (m.tipo='ENTRADA' AND (m.id_item_entrada IS NULL OR m.id_item_venda IS NOT NULL
       OR ie.id_produto<>m.id_produto OR ie.quantidade<>m.quantidade))
   OR (m.tipo='SAIDA' AND (m.id_item_venda IS NULL OR m.id_item_entrada IS NOT NULL
       OR iv.id_produto<>m.id_produto OR iv.quantidade<>m.quantidade))
   OR m.tipo NOT IN ('ENTRADA','SAIDA');

-- A08 — Existem preços ou quantidades inválidos?
-- Verifica: RN03, RN06 e RN07 (limites básicos de estoque e quantidades).
SELECT 'produto' AS tabela,id_produto AS id_registro FROM produto
WHERE preco_venda<=0 OR quantidade_estoque<0 OR estoque_minimo<0
UNION ALL
SELECT 'item_venda',id_item_venda FROM item_venda
WHERE quantidade<=0 OR preco_unitario<=0 OR subtotal<0
UNION ALL
SELECT 'item_entrada',id_item_entrada FROM item_entrada
WHERE quantidade<=0 OR custo_unitario<=0 OR subtotal<0;
